 // ---------- Presence / last seen ----------
 let presenceTimer=null, presenceBusy=false;
 async function touchPresence(){const d=DB(),u=USER();if(!d||!u||presenceBusy||document.visibilityState==='hidden')return;presenceBusy=true;try{const {error}=await d.from('profiles').update({last_seen_at:new Date().toISOString()}).eq('id',u.id);if(error)console.debug('[RIM presence]',error.message)}catch(e){console.debug('[RIM presence]',err(e))}finally{presenceBusy=false}}
 function startPresence(){if(window.__RIM_OWN_PRESENCE_OWNED)return;if(presenceTimer)clearInterval(presenceTimer);touchPresence();presenceTimer=setInterval(touchPresence,60000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')touchPresence()});}
 async function showPeerPresence(conv){if(!conv||conv.type!=='direct')return;const d=DB(),u=USER();if(!d||!u)return;try{const {data:members,error}=await d.from('conversation_members').select('user_id').eq('conversation_id',conv.id);if(error)throw error;const peer=(members||[]).find(x=>x.user_id!==u.id);if(!peer)return;const {data:p,error:pe}=await d.from('profiles').select('last_seen_at,show_online,display_name,username').eq('id',peer.user_id).maybeSingle();if(pe)throw pe;const stamp=p?.last_seen_at;const visible=p?.show_online!==false;setStatus(!visible?'Статус скрыт':stamp?('Был(а) в сети '+new Date(stamp).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})):'Давно не заходил(а)');}catch(e){console.debug('[RIM peer presence]',err(e))}}

 // ---------- Realtime conversation ordering ----------
 function sortChats(){const projection=window.RIM?.container?.get?.('conversationState');if(projection)return projection.sort();const rows=chats();if(Array.isArray(rows))rows.sort((a,b)=>new Date(b._rimLastMessageAt||b.last_message_at||b.created_at||0)-new Date(a._rimLastMessageAt||a.last_message_at||a.created_at||0));}
 function moveChatToTop(conversationId,createdAt,body){const rows=chats();const c=rows.find(x=>String(x.id)===String(conversationId));if(!c)return;c._rimLastMessageAt=createdAt||new Date().toISOString();c._rimLastMessagePreview=body||'';sortChats();if(typeof window.renderConversationList==='function')window.renderConversationList();}

 // ---------- Typing indicator using one broadcast channel per open conversation ----------
 let typingChannel=null,typingConv=null,typingTimer=null,typingSentAt=0,typingInputBound=false,readChannel=null;
 async function bindTyping(conv){const d=DB(),u=USER();if(!d||!u||!conv)return;if(typingConv===conv.id&&typingChannel)return;if(typingChannel){try{await d.removeChannel(typingChannel)}catch(_){}typingChannel=null;}if(readChannel){try{await d.removeChannel(readChannel)}catch(_){}readChannel=null;}typingConv=conv.id;typingChannel=d.channel('rim-typing-'+conv.id,{config:{broadcast:{self:false}}});typingChannel.on('broadcast',{event:'typing'},({payload})=>{if(!payload||payload.user_id===u.id||typingConv!==conv.id)return;if(payload.is_typing){setStatus('Печатает…');if(typingTimer)clearTimeout(typingTimer);typingTimer=setTimeout(()=>{if(typingConv===conv.id)showPeerPresence(conv)},2600)}else if(typingConv===conv.id)showPeerPresence(conv)}).subscribe();if(!window.__RIM_READ_RECEIPTS_OWNED){readChannel=d.channel('rim-read-receipts-'+conv.id).on('postgres_changes',{event:'*',schema:'public',table:'conversation_read_state',filter:'conversation_id=eq.'+conv.id},()=>{if(typingConv===conv.id)updateOwnTicks()}).subscribe();}}
 function sendTyping(on){if(!typingChannel||!USER())return;const now=Date.now();if(on&&now-typingSentAt<700)return;typingSentAt=now;typingChannel.send({type:'broadcast',event:'typing',payload:{user_id:USER().id,is_typing:!!on}}).catch(()=>{});}
 function bindTypingInput(){const input=$('messageInput');if(!input||typingInputBound)return;typingInputBound=true;input.addEventListener('input',()=>{const on=!!input.value.trim();sendTyping(on);if(typingTimer)clearTimeout(typingTimer);if(on)typingTimer=setTimeout(()=>sendTyping(false),1700)});input.addEventListener('blur',()=>sendTyping(false));}

 // ---------- Read receipts ----------
 const markConversationRead=()=>window.markConversationRead?.();
 async function updateOwnTicks(){if(window.__RIM_READ_RECEIPTS_OWNED)return;const d=DB(),u=USER(),c=active();if(!d||!u||!c)return;try{const {data,error}=await d.from('conversation_read_state').select('last_read_at').eq('conversation_id',c.id).neq('user_id',u.id);if(error)throw error;const last=(data||[]).reduce((v,x)=>!v||new Date(x.last_read_at)>new Date(v)?x.last_read_at:v,null);for(const m of msgs().filter(x=>x.sender_id===u.id)){const el=document.querySelector('.message[data-id="'+CSS.escape(String(m.id))+'"]');const meta=el?.querySelector('.message-meta');if(!meta)continue;let tick=meta.querySelector('.rim-release-check');if(!tick){tick=document.createElement('span');tick.className='rim-release-check';tick.textContent='✓';tick.title='Отправлено';meta.append(tick)}if(last&&new Date(last)>=new Date(m.created_at)){tick.textContent='✓✓';tick.title='Прочитано'}}}catch(e){console.debug('[RIM ticks]',err(e))}}
 const oldRender=window.renderMessages;
 if(typeof oldRender==='function'&&!state.readTickRenderer){window.renderMessages=async function(){const out=await oldRender.apply(this,arguments);if(!window.__RIM_READ_RECEIPTS_OWNED)await updateOwnTicks();return out};state.readTickRenderer=true;}

 // ---------- Channel settings: a real editor, independent from fragile legacy modal state ----------
 async function openChannelSettings(){if(window.__RIM_CHANNEL_SETTINGS_OWNED&&typeof window.rimOpenChannelSettings==='function')return window.rimOpenChannelSettings();const d=DB(),u=USER();let c=window.currentChannel;try{if(!c&&typeof currentChannel!=='undefined')c=currentChannel}catch(_){}if(!c&&state.channelId){const {data}=await d.from('channels').select('*').eq('id',state.channelId).maybeSingle();c=data}if(!d||!u||!c)return say('Не удалось определить открытый канал.');let member=null;const {data:m,error:me}=await d.from('channel_members').select('role').eq('channel_id',c.id).eq('user_id',u.id).maybeSingle();if(me)throw me;member=m;const allowed=c.owner_id===u.id||member?.role==='admin'||!!(window.isImperator?.());if(!allowed)return say('Настройки доступны владельцу и администраторам канала.');const modal=$('modalRoot');const body=`<div class="rim-release-channel-settings"><h2 style="margin:0">Настройки канала</h2><label>Название<input id="rimRelChTitle" class="field" maxlength="100" value="${esc(c.title)}"></label><label>Описание<textarea id="rimRelChDesc" class="field" rows="3" maxlength="2000">${esc(c.description||'')}</textarea></label><label>Адрес канала (username)<input id="rimRelChUsername" class="field" maxlength="32" value="${esc(c.username||'')}"></label><label>Доступ<select id="rimRelChPublic" class="field"><option value="true" ${c.is_public?'selected':''}>Публичный</option><option value="false" ${!c.is_public?'selected':''}>Закрытый</option></select></label><div class="rim-release-status">Настройки сохраняются непосредственно в Supabase.</div><div class="rim-release-toolbar"><button class="primary-btn" id="rimRelChSave">Сохранить</button><button class="action-btn" id="rimRelChCancel">Отмена</button></div></div>`;if(typeof window.showModal==='function')window.showModal(body);else if(modal){modal.innerHTML=body;modal.classList.remove('hidden')}else return say('Окно настроек недоступно.');$('rimRelChCancel')?.addEventListener('click',()=>window.closeModal?.());$('rimRelChSave')?.addEventListener('click',async()=>{const title=$('rimRelChTitle')?.value.trim(),description=$('rimRelChDesc')?.value.trim()||'',username=$('rimRelChUsername')?.value.trim().toLowerCase()||'',is_public=$('rimRelChPublic')?.value==='true';if(!title)return say('Введите название канала.');if(username&&!/^[a-z0-9_]{3,32}$/.test(username))return say('Username: 3–32 символа, латиница, цифры и _.');const b=$('rimRelChSave');b.disabled=true;try{const {data,error}=await d.from('channels').update({title,description,username:username||null,is_public}).eq('id',c.id).select('*').single();if(error)throw error;window.currentChannel=data;try{currentChannel=data}catch(_){}window.closeModal?.();say('Настройки канала сохранены.');if(typeof window.openChannel==='function')await window.openChannel(data.id)}catch(e){say('Не удалось сохранить настройки: '+err(e))}finally{if(b)b.disabled=false}})}
 window.rimOpenChannelSettings=openChannelSettings;
 const oldOpenChannel=window.openChannel;if(typeof oldOpenChannel==='function'&&!state.channelIdHook){window.openChannel=async function(id){state.channelId=id;const result=await oldOpenChannel.apply(this,arguments);try{const c=window.currentChannel||(typeof currentChannel!=='undefined'?currentChannel:null);if(c)state.channelId=c.id}catch(_){}return result};state.channelIdHook=true;}

 // ---------- Music: deduplicated records, batched signed URLs, fast local-file upload ----------
 let musicRows=[],musicToken=0,musicLoadPromise=null,musicUrls=new Map();
 function ensureMusicUpload(){const sec=$('musicSection'),list=$('musicList');if(!sec||!list)return;$('musicTitle')?.closest('.card')?.style.setProperty('display','none','important');$('rimLocalMusic')?.remove();$('rimMusicToolbarStable')?.remove();if($('rimReleaseMusicUpload'))return;const box=document.createElement('section');box.id='rimReleaseMusicUpload';box.className='rim-release-upload';box.innerHTML=`<div style="font-weight:700;margin-bottom:5px">Добавить музыку с устройства</div><div class="rim-release-status">Выбери MP3, M4A, AAC, OGG, WAV или WEBM. После загрузки файл появится в каталоге.</div><div class="rim-release-toolbar"><input id="rimRelMusicSearch" class="field" placeholder="Поиск по названию или исполнителю" style="flex:1;min-width:150px"><select id="rimRelMusicSort" class="field"><option value="newest">Сначала новые</option><option value="title">По названию</option><option value="artist">По исполнителю</option></select></div><div id="rimRelMusicStats" class="rim-release-status"></div><input id="rimRelMusicTitle" class="field" placeholder="Название (необязательно)"><input id="rimRelMusicArtist" class="field" placeholder="Исполнитель (необязательно)"><select id="rimRelMusicVisibility" class="field"><option value="private">Только я</option><option value="public">Для всех пользователей</option></select><input id="rimRelMusicFile" class="field" type="file" accept="audio/*,.mp3,.m4a,.aac,.ogg,.opus,.wav,.webm"><button id="rimRelMusicUploadBtn" class="primary-btn" style="width:100%;margin-top:8px">Загрузить файл</button><div id="rimRelMusicUploadStatus" class="rim-release-status" aria-live="polite"></div>`;sec.insertBefore(box,list);$('rimRelMusicUploadBtn').addEventListener('click',uploadMusicFile);$('rimRelMusicSearch').addEventListener('input',renderMusicRows);$('rimRelMusicSort').addEventListener('change',renderMusicRows)}
 async function loadMusic(){if(window.__RIM_MUSIC_OWNED&&typeof window.loadMusic==='function'&&window.loadMusic!==loadMusic)return window.loadMusic();if(typeof window.rimOpenMusic==='function')return window.rimOpenMusic();const d=DB(),u=USER(),list=$('musicList');if(!d||!u||!list)return;if(musicLoadPromise)return musicLoadPromise;const token=++musicToken;ensureMusicUpload();list.innerHTML='<div class="loading">Загружаем каталог…</div>';musicLoadPromise=(async()=>{try{const {data,error}=await d.from('music_tracks').select('id,user_id,title,artist,file_path,visibility,created_at,sort_order').order('created_at',{ascending:false}).limit(500);if(error)throw error;if(token!==musicToken)return;const map=new Map();for(const t of data||[]){if(t?.id&&t.file_path){const key=String(t.user_id)+'|'+String(t.file_path);if(!map.has(key))map.set(key,t)}}musicRows=[...map.values()];const paths=[...new Set(musicRows.map(t=>t.file_path))];const urlMap=new Map();for(let i=0;i<paths.length;i+=80){const chunk=paths.slice(i,i+80);const {data:urls,error:ue}=await d.storage.from('music-library').createSignedUrls(chunk,3600);if(ue)console.warn('[RIM music signed urls]',ue.message);for(const x of urls||[])if(x.path&&x.signedUrl)urlMap.set(x.path,x.signedUrl)}if(token!==musicToken)return;musicUrls=urlMap;renderMusicRows();if(!musicRows.length)list.innerHTML='<div class="empty-state">Каталог пока пуст. Добавь первый трек выше.</div>'}catch(e){if(token===musicToken)list.innerHTML=`<div class="notice">Не удалось загрузить музыку: ${esc(err(e))}</div>`}finally{musicLoadPromise=null}})();return musicLoadPromise}
 function renderMusicRows(){const list=$('musicList'),u=USER();if(!list)return;const q=$('rimRelMusicSearch')?.value.trim().toLocaleLowerCase('ru')||'',sort=$('rimRelMusicSort')?.value||'newest';let rows=musicRows.filter(t=>(`${t.title||''} ${t.artist||''}`).toLocaleLowerCase('ru').includes(q));if(sort==='title')rows.sort((a,b)=>(a.title||'').localeCompare(b.title||'','ru'));else if(sort==='artist')rows.sort((a,b)=>(a.artist||'').localeCompare(b.artist||'','ru'));else rows.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const stats=$('rimRelMusicStats');if(stats)stats.textContent=`В каталоге: ${musicRows.length} · Ваших треков: ${musicRows.filter(t=>t.user_id===u?.id).length}`;const frag=document.createDocumentFragment();for(const t of rows){const card=document.createElement('article');card.className='rim-release-track';card.dataset.trackId=t.id;const title=document.createElement('div');title.className='rim-release-track-title';title.textContent=t.title||'Без названия';const meta=document.createElement('div');meta.className='rim-release-status';meta.textContent=`${t.artist||'Неизвестный исполнитель'} · ${t.visibility==='public'?'public':'private'}${t.user_id===u?.id?' · Ваш трек':''} · ${new Date(t.created_at).toLocaleString('ru-RU')}`;card.append(title,meta);const url=musicUrls.get(t.file_path);if(url){const audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.src=url;audio.addEventListener('error',()=>{const e=document.createElement('div');e.className='rim-release-status';e.textContent='Файл не удалось открыть. Проверь доступ к хранилищу.';card.append(e)},{once:true});card.append(audio)}else{const e=document.createElement('div');e.className='rim-release-status';e.textContent='Ссылка на аудиофайл недоступна.';card.append(e)}frag.append(card)}list.replaceChildren(frag);if(!rows.length)list.innerHTML=musicRows.length?'<div class="empty-state">По запросу ничего не найдено.</div>':'<div class="empty-state">Каталог пока пуст. Добавь первый трек выше.</div>'}
 async function uploadMusicFile(){const d=DB(),u=USER(),file=$('rimRelMusicFile')?.files?.[0],btn=$('rimRelMusicUploadBtn'),out=$('rimRelMusicUploadStatus');if(!d||!u)return say('Сначала войди в РИМ.');if(!file)return say('Выбери аудиофайл.');if(!file.type.startsWith('audio/')&&!/\.(mp3|m4a|aac|ogg|opus|wav|webm)$/i.test(file.name))return say('Выбранный файл не распознан как аудио.');if(file.size>20*1024*1024)return say('Максимальный размер трека — 20 МБ (ограничение хранилища).');btn.disabled=true;out.textContent='Загрузка файла…';const ext=(file.name.split('.').pop()||'audio').toLowerCase().replace(/[^a-z0-9]/g,'')||'audio';const mimeByExt={mp3:'audio/mpeg',m4a:'audio/x-m4a',aac:'audio/aac',ogg:'audio/ogg',opus:'audio/ogg',wav:'audio/wav',webm:'audio/webm'};const contentType=file.type||mimeByExt[ext];if(!contentType||!['audio/mpeg','audio/mp3','audio/x-m4a','audio/mp4','audio/aac','audio/ogg','audio/wav','audio/webm'].includes(contentType)){btn.disabled=false;return say('Формат не поддерживается хранилищем. Используй MP3, M4A, AAC, OGG, WAV или WEBM.')}const path=`${u.id}/${crypto.randomUUID()}.${ext}`;try{const {error:up}=await d.storage.from('music-library').upload(path,file,{contentType,upsert:false});if(up)throw up;const title=$('rimRelMusicTitle')?.value.trim()||file.name.replace(/\.[^.]+$/,'');const artist=$('rimRelMusicArtist')?.value.trim()||'';const visibility=$('rimRelMusicVisibility')?.value||'private';const {error:ins}=await d.from('music_tracks').insert({user_id:u.id,title,artist,file_path:path,visibility,sort_order:Date.now()%2147483647});if(ins){await d.storage.from('music-library').remove([path]);throw ins}$('rimRelMusicTitle').value='';$('rimRelMusicArtist').value='';$('rimRelMusicFile').value='';out.textContent='Файл загружен.';musicLoadPromise=null;await loadMusic();say('Трек добавлен в музыкальный каталог.')}catch(e){out.textContent='Ошибка загрузки: '+err(e);say('Не удалось добавить трек: '+err(e))}finally{btn.disabled=false}}
 window.loadMusic=loadMusic;window.uploadMusic=uploadMusicFile;
 const oldShowSection=window.showSection;if(typeof oldShowSection==='function'&&!state.lazyMusic){window.showSection=function(name){const out=oldShowSection.apply(this,arguments);if(name==='music')loadMusic();return out};state.lazyMusic=true;}

 // ---------- Voice messages: record -> upload -> metadata -> ordinary audio attachment ----------
 let recorder=null,recordChunks=[],recordStart=0,recordStream=null,recordBtn=null;
 function ensureVoiceButton(){if(window.__RIM_VOICE_OWNED)return;const input=$('messageInput');if(!input||$('rimReleaseVoiceBtn'))return;const composer=input.closest('.composer')||input.parentElement;const b=document.createElement('button');b.type='button';b.id='rimReleaseVoiceBtn';b.className='rim-release-voice-btn';b.title='Записать голосовое сообщение';b.setAttribute('aria-label','Записать голосовое сообщение');b.textContent='🎙';b.addEventListener('click',toggleVoiceRecording);composer?.insertBefore(b,input);recordBtn=b;}
 async function toggleVoiceRecording(){if(recorder&&recorder.state==='recording'){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return say('Запись голосовых не поддерживается этим браузером. Открой РИМ по HTTPS и разреши доступ к микрофону.');try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(x=>MediaRecorder.isTypeSupported?.(x))||'';recorder=new MediaRecorder(recordStream,mime?{mimeType:mime}:undefined);recordChunks=[];recordStart=Date.now();recorder.ondataavailable=e=>{if(e.data?.size)recordChunks.push(e.data)};recorder.onstop=async()=>{recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;recordBtn?.classList.remove('recording');recordBtn.textContent='🎙';const blob=new Blob(recordChunks,{type:recorder.mimeType||'audio/webm'});const duration=Math.max(1,Math.round((Date.now()-recordStart)/1000));if(blob.size)await sendVoice(blob,duration)};recorder.start(250);recordBtn?.classList.add('recording');recordBtn.textContent='■';say('Запись началась. Нажми ■, чтобы отправить.')}catch(e){recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;say('Не удалось начать запись: '+err(e))}}
 async function sendVoice(blob,duration){if(window.__RIM_VOICE_OWNED&&typeof window.rimSendVoice==='function')return window.rimSendVoice(...arguments);const d=DB(),u=USER(),c=active();if(!d||!u||!c)return say('Сначала открой переписку.');const id=crypto.randomUUID(),ext=blob.type.includes('mp4')?'m4a':'webm',path=`${u.id}/${c.id}/${id}.${ext}`,mime=blob.type||'audio/webm';try{const {error:up}=await d.storage.from('chat-files').upload(path,blob,{contentType:mime,upsert:false});if(up)throw up;const {data:msg,error:me}=await d.from('chat_messages').insert({conversation_id:c.id,sender_id:u.id,body:''}).select('id,created_at').single();if(me)throw me;const {error:att}=await d.from('chat_message_attachments').insert({message_id:msg.id,storage_path:path,file_name:`Голосовое сообщение.${ext}`,mime_type:mime,media_kind:'voice',byte_size:blob.size,duration_seconds:duration});if(att){await d.from('chat_messages').delete().eq('id',msg.id);await d.storage.from('chat-files').remove([path]);throw att}const {error:voice}=await d.from('chat_voice_messages').insert({conversation_id:c.id,sender_id:u.id,storage_path:path,duration_seconds:duration,waveform:[]});if(voice)console.warn('[RIM voice metadata]',voice.message);if(typeof window.loadMessages==='function')await window.loadMessages();moveChatToTop(c.id,msg.created_at,'Голосовое сообщение');}catch(e){say('Не удалось отправить голосовое: '+err(e))}}

 // ---------- Lifecycle wiring ----------
 const oldOpen=window.openConversation;if(typeof oldOpen==='function'&&!state.openHooks){window.openConversation=async function(id){const result=await oldOpen.apply(this,arguments);const c=active()||chats().find(x=>String(x.id)===String(id));if(c){if(!window.__RIM_TYPING_PRESENCE_OWNED){await bindTyping(c);await showPeerPresence(c)}if(!window.__RIM_READ_RECEIPTS_OWNED)await updateOwnTicks()}return result};state.openHooks=true;}
 function boot(){if(!window.__RIM_OWN_PRESENCE_OWNED)startPresence();if(!window.__RIM_TYPING_PRESENCE_OWNED)bindTypingInput();if(!window.__RIM_VOICE_OWNED)ensureVoiceButton();ensureMusicUpload();}
 try{DB()?.auth?.onAuthStateChange?.((event,session)=>{if(session?.user&&(event==='SIGNED_IN'||event==='TOKEN_REFRESHED')){setTimeout(()=>{if(!window.__RIM_OWN_PRESENCE_OWNED)startPresence();if(!window.__RIM_TYPING_PRESENCE_OWNED)bindTypingInput();if(!window.__RIM_VOICE_OWNED)ensureVoiceButton()},0)}if(event==='SIGNED_OUT'){if(presenceTimer)clearInterval(presenceTimer);presenceTimer=null;if(typingChannel){DB()?.removeChannel(typingChannel).catch(()=>{});typingChannel=null}if(readChannel){DB()?.removeChannel(readChannel).catch(()=>{});readChannel=null}}})}catch(e){console.debug('[RIM auth lifecycle]',err(e))}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
